import{_ as t,o as a,c as _,a4 as p}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"山东潍坊：“智慧农业”点亮特色产业富民路","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"山东潍坊：“智慧农业”点亮特色产业富民路","date":"2026-06-06T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202604/t20260429_6483784.htm","summary":"走进山东潍坊寿光市洛城街道尧水村,连片的高标准冬暖式大棚整齐排列,棚内绿意盎然,奶油黄瓜、五彩椒、番茄等10多个品种的蔬菜正处于采收旺季。\\n“我们施用含多种中草药成分的肥料,能抑制病虫害,种出来的黄瓜皮薄、清脆还有奶香味,最高卖到15元一斤,每亩地的年收益超过10万元。”寿光市寿诚尧水果蔬农民专业合作社联合社理事长李兴刚说。\\n...\\n","contentHash":"a1834b880cd8d176c59b1da5cf371f5b","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-06-06-山东潍坊-智慧农业-点亮特色产业富民路.md","filePath":"news/2026-06-06-山东潍坊-智慧农业-点亮特色产业富民路.md"}'),r={name:"news/2026-06-06-山东潍坊-智慧农业-点亮特色产业富民路.md"};function n(s,e,o,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[p('<h1 id="山东潍坊-智慧农业-点亮特色产业富民路" tabindex="-1">山东潍坊：“智慧农业”点亮特色产业富民路 <a class="header-anchor" href="#山东潍坊-智慧农业-点亮特色产业富民路" aria-label="Permalink to &quot;山东潍坊：“智慧农业”点亮特色产业富民路&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202604/t20260429_6483784.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-06-06 摘要: 走进山东潍坊寿光市洛城街道尧水村,连片的高标准冬暖式大棚整齐排列,棚内绿意盎然,奶油黄瓜、五彩椒、番茄等10多个品种的蔬菜正处于采收旺季。 “我们施用含多种中草药成分的肥料,能抑制病虫害,种出来的黄瓜皮薄、清脆还有奶香味,最高卖到15元一斤,每亩地的年收益超过10万元。”寿光市寿诚尧水果蔬农民专业合作社联合社理事长李兴刚说。 ...</p></blockquote><p>“我们施用含多种中草药成分的肥料,能抑制病虫害,种出来的黄瓜皮薄、清脆还有奶香味,最高卖到15元一斤,每亩地的年收益超过10万元。”寿光市寿诚尧水果蔬农民专业合作社联合社理事长李兴刚说。</p><p>寿光市寿诚尧水果蔬农民专业合作社联合社理事长李兴刚在大棚内查看奶油黄瓜长势。新华社记者王志 摄</p><p>曾经“靠天吃饭”的种菜模式,如今摇身变成“一键操控”的智慧农业。记者在大棚里看到,自动卷帘机、电动喷灌机、自动打药机等智能设备一应俱全。</p><p>“现在种菜全靠电,棚内温度湿度自动显示,天冷开保温、天热开遮阳、干了开喷灌,手机一点就能远程操控,种大棚越来越轻松。”从事蔬菜种植20多年的联合社菜农李泽龙说,今年他种了6亩五彩椒大棚,预计亩产量能达到2万斤,亩均纯收益8万多元。</p><p>“电气化智能管理省心又高产。”李兴刚说,联合社共种植蔬菜2500多亩,高端蔬菜大棚300多个,年销售额1亿多元,带动6个村的数百户菜农增收致富。</p><p>寿光市农业农村局蔬菜技术推广科科长刘春香说,近年来,寿光以工业互联网思维对农业基础设施、产业装备进行改造提升,新建大棚的智能化装备普及率、物联网应用率、标准化生产推广率均超过85%,劳动生产率提升30%至50%。</p><p>科技赋能让传统农业迈入精准化、智能化新阶段。</p><p>在昌乐县的潍坊鲁乐农农业科技有限公司智能温室育苗基地,6座高标准大棚孕育着20余个果蔬品种种苗。基地搭建“环境感知—智能决策—精准执行”体系,AI图像识别算法可精准识别90%以上病虫害,高精度传感器实现温度湿度精准调控。</p><p>“以前靠经验摸规律,现在传感器实时传数据,手机就能一键调控水肥、通风。供电公司专门为基地升级了线路,保障基地用电设备稳定运行,基地肥料利用率提升了三成多,节水率达50%,种苗成活率从80%提高到95%。”公司总经理杨凯说,基地年培育优质种苗1500万株,远销10余个省份,带动周边500余户农户增收。</p><p>国网昌乐县供电公司工作人员到潍坊鲁乐农公司智能温室育苗基地开展用电设备隐患排查。(受访者供图)</p><p>智慧农业的蓬勃发展,离不开稳定的电力支撑。“我们精准对接智慧农业用电需求,针对农业生产规律制定‘二十四节气’服务台账,供电服务队深入智慧农业园区及各农业合作社开展专项巡检,提前对接育苗、灌溉等关键节点,排查线路隐患,确保智能设备不断电。”国网昌乐县供电公司营销部负责人李明说。</p><p>从“会种地”到“慧种地”,物联网智能化控制管理、智能水肥一体机应用、智能植保机作业等新技术赋能现代农业发展,助力设施农业提质增效,为乡村振兴注入新动能。(记者王志)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202604/t20260429_6483784.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',15)])])}const h=t(r,[["render",n]]);export{i as __pageData,h as default};
